/*
 * test_config_parser_vectors.S — drive lib/config_parser.S against
 * every vector in tests/func/network_conf_vectors.tsv (I9).
 *
 * The vector table _cp_vectors is generated by
 * scripts/gen_config_parser_vectors.py at build time (see the
 * Makefile rule for build/config_parser_vectors.S). Per-record
 * layout: name(8) + expected(4) + code(4) + input(8) + len(4) +
 * pad(4) = 32 bytes. Sentinel = name pointer 0.
 *
 * Each vector is one logical test: PASS rows expect config_parse
 * to return 0; FAIL rows expect it to return the documented error
 * code. Per-vector test_pass / test_fail emits one line of output
 * per vector, named by the vector's `name` column.
 *
 * net_cfg state is saved at entry and restored at exit so the
 * iteration's mutations don't leak into downstream tests
 * (test_eth_*, test_arp_*, etc. rely on the QEMU compile-time
 * defaults).
 */

.include "net.inc"

.global test_config_parse_vectors

.section .text

/* x19 = current vector pointer (callee-saved across bl)
 * x20 = current vector's name pointer (passed to test_pass/fail) */
test_config_parse_vectors:
    stp     x29, x30, [sp, #-32]!
    mov     x29, sp
    stp     x19, x20, [sp, #16]

    /* --- Save current net_cfg state to _cp_save_state. --- */
    adrp    x10, _cp_save_state
    add     x10, x10, :lo12:_cp_save_state

    /* MAC (6 bytes) at offset 0. */
    adrp    x9, net_our_mac
    add     x9, x9, :lo12:net_our_mac
    ldrb    w11, [x9, #0];  strb w11, [x10, #0]
    ldrb    w11, [x9, #1];  strb w11, [x10, #1]
    ldrb    w11, [x9, #2];  strb w11, [x10, #2]
    ldrb    w11, [x9, #3];  strb w11, [x10, #3]
    ldrb    w11, [x9, #4];  strb w11, [x10, #4]
    ldrb    w11, [x9, #5];  strb w11, [x10, #5]

    /* IP fields (4 bytes each) at offsets 8/12/16/20. */
    adrp    x9, net_our_ip
    add     x9, x9, :lo12:net_our_ip
    ldr     w11, [x9];      str  w11, [x10, #8]

    adrp    x9, net_gw_ip
    add     x9, x9, :lo12:net_gw_ip
    ldr     w11, [x9];      str  w11, [x10, #12]

    adrp    x9, net_ntp_ip
    add     x9, x9, :lo12:net_ntp_ip
    ldr     w11, [x9];      str  w11, [x10, #16]

    adrp    x9, net_netmask
    add     x9, x9, :lo12:net_netmask
    ldr     w11, [x9];      str  w11, [x10, #20]

    /* hostname_len at offset 24. */
    adrp    x9, net_hostname_len
    add     x9, x9, :lo12:net_hostname_len
    ldr     w11, [x9];      str  w11, [x10, #24]

    /* hostname (64 bytes) at offset 32 (8-byte aligned for ldp/stp). */
    adrp    x9, net_hostname
    add     x9, x9, :lo12:net_hostname
    add     x12, x10, #32
    ldp     x11, x13, [x9, #0];   stp x11, x13, [x12, #0]
    ldp     x11, x13, [x9, #16];  stp x11, x13, [x12, #16]
    ldp     x11, x13, [x9, #32];  stp x11, x13, [x12, #32]
    ldp     x11, x13, [x9, #48];  stp x11, x13, [x12, #48]

    /* --- Iterate the vector table. --- */
    adrp    x19, _cp_vectors
    add     x19, x19, :lo12:_cp_vectors

.Ltcpv_loop:
    ldr     x20, [x19]              /* name ptr; null = end */
    cbz     x20, .Ltcpv_done

    /* Load record fields. */
    ldr     w0, [x19, #8]           /* expected: 0=PASS, 1=FAIL */
    ldr     w1, [x19, #12]          /* expected error code */
    ldr     x2, [x19, #16]          /* input ptr */
    ldr     w3, [x19, #24]          /* input len */

    /* Stash expected/code across config_parse. */
    stp     x0, x1, [sp, #-16]!
    mov     x0, x2
    mov     x1, x3
    bl      config_parse
    ldp     x4, x5, [sp], #16       /* x4=expected, x5=code */

    cbz     w4, .Ltcpv_expect_pass
    /* FAIL row: w0 must equal w5. */
    cmp     w0, w5
    b.ne    .Ltcpv_fail
    b       .Ltcpv_pass
.Ltcpv_expect_pass:
    /* PASS row: w0 must be 0. */
    cbnz    w0, .Ltcpv_fail
.Ltcpv_pass:
    mov     x0, x20
    bl      test_pass
    b       .Ltcpv_next
.Ltcpv_fail:
    mov     x0, x20
    bl      test_fail
.Ltcpv_next:
    add     x19, x19, #32
    b       .Ltcpv_loop

.Ltcpv_done:
    /* --- Restore net_cfg state from _cp_save_state. --- */
    adrp    x10, _cp_save_state
    add     x10, x10, :lo12:_cp_save_state

    adrp    x9, net_our_mac
    add     x9, x9, :lo12:net_our_mac
    ldrb    w11, [x10, #0]; strb w11, [x9, #0]
    ldrb    w11, [x10, #1]; strb w11, [x9, #1]
    ldrb    w11, [x10, #2]; strb w11, [x9, #2]
    ldrb    w11, [x10, #3]; strb w11, [x9, #3]
    ldrb    w11, [x10, #4]; strb w11, [x9, #4]
    ldrb    w11, [x10, #5]; strb w11, [x9, #5]

    adrp    x9, net_our_ip
    add     x9, x9, :lo12:net_our_ip
    ldr     w11, [x10, #8];  str  w11, [x9]

    adrp    x9, net_gw_ip
    add     x9, x9, :lo12:net_gw_ip
    ldr     w11, [x10, #12]; str  w11, [x9]

    adrp    x9, net_ntp_ip
    add     x9, x9, :lo12:net_ntp_ip
    ldr     w11, [x10, #16]; str  w11, [x9]

    adrp    x9, net_netmask
    add     x9, x9, :lo12:net_netmask
    ldr     w11, [x10, #20]; str  w11, [x9]

    adrp    x9, net_hostname_len
    add     x9, x9, :lo12:net_hostname_len
    ldr     w11, [x10, #24]; str  w11, [x9]

    adrp    x9, net_hostname
    add     x9, x9, :lo12:net_hostname
    add     x12, x10, #32
    ldp     x11, x13, [x12, #0];  stp x11, x13, [x9, #0]
    ldp     x11, x13, [x12, #16]; stp x11, x13, [x9, #16]
    ldp     x11, x13, [x12, #32]; stp x11, x13, [x9, #32]
    ldp     x11, x13, [x12, #48]; stp x11, x13, [x9, #48]

    ldp     x19, x20, [sp, #16]
    ldp     x29, x30, [sp], #32
    ret


.section .bss
.balign 8
_cp_save_state:
    .space  96                      /* 6 mac + 2 pad + 4*4 IPs + 4 len + 4 pad + 64 hostname */
